internal static class TestInitialPreparationOffer01 {
 static int checks;static readonly JavaScriptSerializer json=new JavaScriptSerializer();static string diagnosticFolder,phase="entry";static long cacheSeedBefore,captureBefore,captureAfter;static bool forceExpired;
 static void Check(bool yes,string why){checks++;if(!yes)throw new Exception(why);}
 static void Wait(Func<bool> condition,int milliseconds,string why){var timer=Stopwatch.StartNew();while(!condition()){if(timer.ElapsedMilliseconds>=milliseconds)throw new Exception(why);Thread.Sleep(5);}}
 static WorldWarmupSupervisor Worker {get{return (WorldWarmupSupervisor)typeof(InstalledWorldWarmup).GetField("worker",BindingFlags.NonPublic|BindingFlags.Static).GetValue(null);}}
 static void Capture(GameplayRuntime runtime,double x=0){Thread.Sleep(60);Rage.Native.NativeFunction.CameraX=x;long now=Stopwatch.GetTimestamp();cacheSeedBefore=forceExpired?now-Stopwatch.Frequency/20:now;typeof(CameraSampler).GetField("cached",BindingFlags.NonPublic|BindingFlags.Static).SetValue(null,new CameraObservation{Before=cacheSeedBefore,After=cacheSeedBefore,Observed=cacheSeedBefore,Position=new[]{forceExpired?-999d:x,0d,1d},Forward=new[]{0d,1d,0d},Up=new[]{0d,0d,1d}});captureBefore=Stopwatch.GetTimestamp();try{typeof(PlayableEntry).GetMethod("Capture",BindingFlags.NonPublic|BindingFlags.Static).Invoke(null,new object[]{runtime});}finally{captureAfter=Stopwatch.GetTimestamp();}}
 static int Main(string[] args){try{
  string scenario=args[0],power=args[1],game=Path.GetDirectoryName(Assembly.GetExecutingAssembly().Location),root=Path.GetDirectoryName(game),output=Path.Combine(root,".local","world"),parser=Path.Combine(root,"parser"),tools=Path.Combine(root,"tools");diagnosticFolder=root;phase="authored-input-setup";foreach(string folder in new[]{output,parser,tools,Path.Combine(game,"Plugins")})Directory.CreateDirectory(folder);
  string script=Path.Combine(tools,"Prepare-InstalledAudioWorld.ps1"),core=Path.Combine(parser,"CodeWalker.Core.dll");File.WriteAllText(core,"inert original parser identity");File.WriteAllText(script,"param($GameRoot,$CodeWalkerRoot,$OutputRoot,$MaximumSeconds,$MaximumStageSeconds,$MaximumMemoryMiB,$MaximumGeometryResources)\n[IO.File]::WriteAllText((Join-Path $OutputRoot 'original-worker-started.txt'),'inert')\nStart-Sleep -Milliseconds 1800\n");
  var configuration=new WarmupConfiguration{Schema=1,Enabled=scenario!="disabled",WorkspaceRoot=root,GameRoot=game,GameExecutableSHA256=WorldWarmupSupervisor.Hash(Assembly.GetExecutingAssembly().Location),CodeWalkerRoot=parser,CodeWalkerCoreSHA256=WorldWarmupSupervisor.Hash(core),PowerShellPath=power,PowerShellSHA256=WorldWarmupSupervisor.Hash(power),OutputRoot=output,Sources=new[]{new WarmupBinding{RelativePath="tools/Prepare-InstalledAudioWorld.ps1",SHA256=WorldWarmupSupervisor.Hash(script)}},MaximumSeconds=20,MaximumStageSeconds=5,MaximumMemoryMiB=256,MaximumGeometryResources=16};
  using(var stream=File.Create(Path.Combine(game,"Plugins","RichAudio.WorldWarmup.json")))new DataContractJsonSerializer(typeof(WarmupConfiguration)).WriteObject(stream,configuration);
  var player=new Rage.Ped{Handle=new Rage.PoolHandle{Value=258,Index=1,Counter=2},MemoryAddress=new IntPtr(100)};var vehicle=new Rage.Vehicle{Handle=new Rage.PoolHandle{Value=772,Index=3,Counter=4},MemoryAddress=new IntPtr(200),Driver=player};player.CurrentVehicle=vehicle;Rage.Game.LocalPlayer.Character=player;var runtime=new GameplayRuntime();string target=Path.Combine(output,"geometry","initial-observation01.json");
  forceExpired=scenario=="expired-cache-negative"||scenario=="native-camera-route";Rage.Native.NativeFunction.RejectCamera=scenario=="expired-cache-negative";phase="first-cold-Capture";
  if(scenario=="expired-cache-negative"){
   Exception failure=null;try{Capture(runtime);}catch(TargetInvocationException error){failure=error.InnerException;}
   Check(failure!=null&&failure.Message=="Unexpected original fixture native: GET_FINAL_RENDERED_CAM_COORD","expired original cache reaches the originally missing authored camera native");
   var evidence=new{scenario,expectedFailure=failure.ToString(),productCacheTtlMs=25,forcedOriginalCacheAgeMs=(captureBefore-cacheSeedBefore)*1000d/Stopwatch.Frequency,captureBefore,captureAfter,clockFrequency=Stopwatch.Frequency,normalFrames=runtime.Frames.Count,hostAttempts=runtime.Attempts,productSourceChanged=false};File.WriteAllText(Path.Combine(root,"expected-camera-cache-failure.json"),json.Serialize(evidence));
   Check(runtime.Frames.Count==0&&runtime.Attempts==0,"incomplete fixture native prevents frame publication and starts no host");System.Console.WriteLine("{\"passed\":true,\"scenario\":\""+scenario+"\",\"checks\":"+checks+",\"expectedOriginalCameraStubFailure\":true,\"noAudioHost\":true,\"originalInputsOnly\":true,\"gameLaunched\":false,\"endpointOpened\":false}");return 0;
  }
  Capture(runtime);Check(runtime.HostPid==0&&runtime.Attempts==0&&runtime.State=="stock-fallback","actual normal Capture offers advisory pose while no audio host exists");Check(!File.Exists(target),"offer before validated configuration performs no file write");
  if(forceExpired){var camera=(CameraObservation)typeof(CameraSampler).GetField("cached",BindingFlags.NonPublic|BindingFlags.Static).GetValue(null);Check(Rage.Native.NativeFunction.CameraCalls==3,"expired cache takes all three authored camera getters");Check(camera.Before>=captureBefore&&camera.After<=captureAfter&&camera.Observed==camera.Before+(camera.After-camera.Before)/2&&camera.Observed>cacheSeedBefore,"actual CameraSampler owns fresh original QPC bracket; expired timestamp is not refreshed");Check(camera.Position[0]==0,"fresh authored camera pose replaces discarded cached pose");}
  if(scenario=="stale")Thread.Sleep(550);
  if(scenario=="cancelled")Worker.Stop();
  if(scenario=="immutable-held")runtime.Frames[0].Listener.Position[0]=333;
  if(scenario=="busy-cancelled"){Directory.CreateDirectory(Path.GetDirectoryName(target));File.WriteAllText(target+".lock","authored shared writer lock");}
  string existing=null;if(scenario=="preserve-existing"||scenario=="invalid-existing-time"){Directory.CreateDirectory(Path.GetDirectoryName(target));existing=json.Serialize(new{Schema=1,Kind="RichAudioInitialWorldObservation01",GameExecutableSHA256=configuration.GameExecutableSHA256,session=runtime.Session,sequence=0,generation=1,geometryTimeMs=scenario=="invalid-existing-time"?-1:42,sourceAgeMs=0,listener=new[]{77d,0d,1d},sources=new double[0][],origin="normal-gameplay-observation",receivedUtc=DateTime.UtcNow.ToString("o")});File.WriteAllText(target,existing);}
  phase="start-validated-preparation";InstalledWorldWarmup.Start();phase="observe-"+scenario;
  if(scenario=="disabled"){Wait(()=>Worker.State=="disabled",2000,"disabled configuration resolves");Check(!File.Exists(target),"disabled bound sidecar cannot write priority");Check(Worker.InitialObservationState=="configuration-disabled","disabled priority state explicit");}
  else if(scenario=="cancelled"){Thread.Sleep(150);Check(!File.Exists(target)&&Worker.InitialObservationState=="cancelled","pre-cancelled held offer cannot write later");}
  else if(scenario=="stale"){Wait(()=>Worker.InitialObservationState=="stale-offer-withheld",2000,"original queued timestamp expires");Check(!File.Exists(target),"validation/queue delay cannot refresh stale camera evidence");Capture(runtime);Capture(runtime);Wait(()=>File.Exists(target),2000,"fresh independent offer recovers advisory priority");Check(Worker.InitialObservationState=="initial-position-retained","stale rejection does not block preparation or fresh retry");}
  else if(scenario=="busy-cancelled"){Wait(()=>Worker.InitialObservationState=="priority-write-deferred",2000,"shared writer lock defers only priority");Worker.Stop();File.Delete(target+".lock");Capture(runtime);Thread.Sleep(1100);Check(!File.Exists(target)&&Worker.InitialObservationState=="cancelled","Stop prevents late write/retry after external lock is released");}
  else if(scenario=="preserve-existing"){Wait(()=>Worker.InitialObservationState=="existing-first-position-preserved",2000,"valid earlier JS-shaped sequence-zero record preserved");Check(File.ReadAllText(target)==existing,"same-game/session valid first file remains byte exact");}
  else{
   Wait(()=>Worker.InitialObservationState=="initial-position-retained",2000,"validated background writer publishes first valid camera pose");var data=json.DeserializeObject(File.ReadAllText(target))as Dictionary<string,object>;Check((string)data["session"]==runtime.Session&&(string)data["GameExecutableSHA256"]==configuration.GameExecutableSHA256,"actual writer binds game/session independently of audio host");Check(Convert.ToInt64(data["sequence"])==0,"actual first valid sequence-zero camera is preserved without renumbering");Check(Convert.ToDouble(data["sourceAgeMs"])<=500&&Convert.ToDouble(data["geometryTimeMs"])>0,"original QPC age includes queue delay");Check(Convert.ToDouble(((object[])data["listener"])[0])==0,"writer owns immutable first-pose copy and replaces semantically invalid prior file");string initial=File.ReadAllText(target);Capture(runtime,scenario=="immutable-held"?333:1);Thread.Sleep(100);Check(File.ReadAllText(target)==initial,"later captures cannot overwrite first valid session position");
  }
  Check(!Worker.OfferInitialObservation01(runtime.Session,1,1,Stopwatch.GetTimestamp(),Stopwatch.Frequency,new[]{100001d,0d,0d}),"producer rejects coordinates outside shared priority contract");InstalledWorldWarmup.Stop();Wait(()=>Worker.State=="cancelled"||Worker.State=="disabled"||Worker.State=="preparation-finished-read-summary",4000,"actual preparation worker closes after Stop");
  System.Console.WriteLine("{\"passed\":true,\"scenario\":\""+scenario+"\",\"checks\":"+checks+",\"noAudioHost\":true,\"originalInputsOnly\":true,\"gameLaunched\":false,\"endpointOpened\":false}");return 0;
 }catch(Exception error){try{var context=new{scenario=args.Length>0?args[0]:null,phase,exception=error.ToString(),workerState=Worker.State,priorityState=Worker.InitialObservationState,clockFrequency=Stopwatch.Frequency,cacheSeedBefore,captureBefore,captureAfter,cacheAgeAtInvocationMs=(captureBefore-cacheSeedBefore)*1000d/Stopwatch.Frequency,authoredCameraCalls=Rage.Native.NativeFunction.CameraCalls,executable=Process.GetCurrentProcess().MainModule.FileName,assembly=Assembly.GetExecutingAssembly().Location,productSourcesModified=false,installedResourcesRead=false};if(diagnosticFolder!=null)File.WriteAllText(Path.Combine(diagnosticFolder,"failure-context.json"),json.Serialize(context));}catch(Exception diagnosticError){System.Console.Error.WriteLine("Original fixture diagnostic failure: "+diagnosticError.Message);}try{InstalledWorldWarmup.Stop();}catch(Exception){}System.Console.Error.WriteLine(error);return 1;}}
}
